    'You do not have permission to scan that site.' => 'No tienes permiso para analizar ese sitio.',
    'You do not have permission to view that scan.' => 'No tienes permiso para ver ese análisis.',
    'You do not have permission to view this asset.' => 'No tienes permiso para ver este recurso.',
    'Your Target WCAG Level is {level}, but this jurisdiction requires AA. A statement claiming that standard would be asserting a level the site was never measured against.' => 'Tu nivel WCAG objetivo es {level}, pero este marco legal exige AA. Una declaración que afirme esa norma estaría reclamando un nivel con el que el sitio nunca se ha medido.',
    '{attribute} contains invalid characters.' => '{attribute} contiene caracteres no válidos.',
    '{attribute} must be a WCAG criterion number, e.g. 1.4.3.' => '{attribute} debe ser un número de criterio WCAG, p. ej. 1.4.3.',
    '{count} with issues' => '{count} con problemas',
    '{feature} is a Pro feature' => '{feature} es una función Pro',
    '{feature} requires the Pro edition.' => '{feature} requiere la edición Pro.',
    '{from} to {to}' => '{from} a {to}',
    '{gap} to target {n}' => '{gap} hasta el objetivo {n}',
