    '{n, plural, =1{# notice} other{# notices}}' => '{n, plural, =1{# aviso} other{# avisos}}',
    '{n, plural, =1{# question from the scans is} other{# questions from the scans are}} still waiting for an answer under Potential issues.' => '{n, plural, =1{# pregunta de los escaneos sigue} other{# preguntas de los escaneos siguen}} esperando respuesta en Problemas potenciales.',
    '{n, plural, =1{# question} other{# questions}} across {p, plural, =1{# page} other{# pages}} {n, plural, =1{is} other{are}} still waiting on a person.' => '{n, plural, =1{# pregunta} other{# preguntas}} en {p, plural, =1{# página} other{# páginas}} {n, plural, =1{sigue esperando} other{siguen esperando}} a una persona.',
    '{n, plural, =1{# remark was reworded without the conformance level changing.} other{# remarks were reworded without the conformance level changing.}}' => '{n, plural, =1{# observación se reformuló sin que cambiara el nivel de conformidad.} other{# observaciones se reformularon sin que cambiara el nivel de conformidad.}}',
    '{n, plural, =1{# warning} other{# warnings}}' => '{n, plural, =1{# advertencia} other{# advertencias}}',
