    '{n, plural, =1{use of the passive voice} other{uses of the passive voice}}' => '{n, plural, =1{uso de la voz pasiva} other{usos de la voz pasiva}}',
    '{n, plural, =1{word or phrase with a plainer alternative} other{words or phrases with plainer alternatives}}' => '{n, plural, =1{palabra o expresión con una alternativa más sencilla} other{palabras o expresiones con alternativas más sencillas}}',
